def resolve(path, cwd, links):
    # Validate cwd
    if not cwd or cwd[0] != '/':
        return None

    # Split path into components
    if path.startswith('/'):
        current = '/'
        components = path.split('/')[1:]
    else:
        current = cwd
        components = path.split('/')

    link_count = 0
    i = 0

    while i < len(components):
        component = components[i]

        # Skip empty components and '.'
        if component == '' or component == '.':
            i += 1
            continue

        # Handle '..'
        if component == '..':
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            i += 1
            continue

        # Append component to current path
        if current == '/':
            new_path = '/' + component
        else:
            new_path = current + '/' + component

        # Check if new_path is a symlink
        if new_path in links:
            link_count += 1
            if link_count > 8:
                return None

            target = links[new_path]

            # Resolve target path
            if target.startswith('/'):
                current = '/'
                target_components = target.split('/')[1:]
            else:
                # Target is relative to the directory containing the link
                if current == '/':
                    current = '/'
                else:
                    current = current.rsplit('/', 1)[0]
                    if current == '':
                        current = '/'
                target_components = target.split('/')

            # Replace current components with target components + remaining components
            components = target_components + components[i+1:]
            i = 0
        else:
            current = new_path
            i += 1

    # Return result without trailing slash, except for '/'
    if current == '/':
        return '/'
    else:
        return current

